import assert from 'node:assert/strict'
import { pathToFileURL } from 'node:url'
import { resolve } from 'node:path'
const y = await import(pathToFileURL(resolve('src/src/index.ts')).href)
const schemas = [undefined, y.CORE_SCHEMA, y.JSON_SCHEMA, y.YAML11_SCHEMA]
const values = [1e21, -1e21, 1.2e21, -1.2e21, Number.MAX_VALUE, -Number.MAX_VALUE]
for (const schema of schemas) {
  for (const value of values) {
    const options = schema ? { schema } : {}
    const scalar = y.dump(value, options)
    assert.equal(y.load(scalar, options), value, `${value} scalar`)
    const collection = y.dump([value, { value }], options)
    const roundTrip = y.load(collection, options)
    assert.equal(roundTrip[0], value, `${value} sequence`)
    assert.equal(roundTrip[1].value, value, `${value} mapping`)
    assert.doesNotMatch(scalar, /e[+-]?\d+/i)
  }
  assert.throws(() => y.load('!!int 1e+21', schema ? { schema } : {}))
}
console.log('large integer round trips and explicit integer validation passed')
